#ifndef WORDS_H
#define WORDS_H

#include <stdint.h>

#include "game.h"

// Defined in the file generated by tools/wordlist.py. Words are packed
// WORD_LEN characters each, without separators.
extern const int word_count;
extern const char word_list[];
extern const int answer_count;
extern const uint16_t answer_order[];
extern const int accented_count;
extern const uint16_t accented_index[];
extern const char accented_text[];

// Returns the index of a lowercase unaccented word, or -1 if it isn't valid.
int word_find(const char *word);
const char *word_text(int index);
// Copies the word as it should be shown, in Latin-1, with its accents.
void word_display(int index, char out[WORD_LEN]);

#endif
